// 多路径关系只提供来源；生前双方须当时成年且在世，死后Legacy许可不在此被读取或复用。
#include "voluntary_relation_source.hpp"
#include "apprenticeship_receipts.hpp"
#include "collateral_recognition_receipts.hpp"
#include <charconv>
namespace hanmo::resident {namespace {
Integer serial(const CommonStore& c,const StableId& id){const auto colon=id.find(':');if(colon==StableId::npos)return -1;const auto digits=id.substr(colon+1);Integer n=0;auto p=std::from_chars(digits.data(),digits.data()+digits.size(),n);return p.ec==std::errc{}&&p.ptr==digits.data()+digits.size()&&n>0&&n<c.state().next_instance_id&&std::to_string(n)==digits?n:-1;}
Status prior(const CommonStore& c,const StableId& source,const StableId& before){const auto& ids=c.state().facts.order();const auto a=std::find(ids.begin(),ids.end(),source),b=before.empty()?ids.end():std::find(ids.begin(),ids.end(),before);if(serial(c,source)<1||a==ids.end()||a>=b||(!before.empty()&&serial(c,source)>=serial(c,before)))return common_failure("VoluntaryRelationSourceOrderMismatch",source);return common_success();}
// 旧人物随后死亡/退出不抹旧计划，但同tick不能把原因移过本次真实Family头。
Status same_side(const CommonStore& c,const StableId& source,const StableId& before){if(before.empty())return common_success();const auto& ids=c.state().facts.order();const auto a=std::find(ids.begin(),ids.end(),source),b=std::find(ids.begin(),ids.end(),before);const auto n=serial(c,source),limit=serial(c,before);return n>0&&limit>0&&n!=limit&&a!=ids.end()&&b!=ids.end()&&((n<limit)==(a<b))?common_success():common_failure("VoluntaryRelationBoundaryOrderMismatch",source);}
Outcome<VoluntaryRelationSource> read(const VoluntaryRelationContext& x,VoluntaryRelationKind kind,const StableId& predecessor,const StableId& successor,const StableId& selected,Integer tick,const StableId& before){
    auto fail=[&](const StableId& code)->Outcome<VoluntaryRelationSource>{return {false,{},common_failure(code,selected.empty()?successor:selected).error};};const auto& c=x.common;
    if(predecessor.empty()||successor.empty()||predecessor==successor||tick<0||tick>c.tick()||(before.empty()&&tick!=c.tick()))return fail("VoluntaryRelationPartiesOrTimeRequired");
    if(!before.empty()){const auto* h=c.state().facts.find(before);if(before.rfind("family:",0)!=0||serial(c,before)<1||!h||h->id!=before||h->domain!="family"||(h->kind!="family_succession_consent"&&h->kind!="family_voluntary_succession"))return fail("VoluntaryRelationActualBoundaryRequired");}
    if(!x.death_origin)return fail("VoluntaryRelationDeathReadRequired");if(x.catalog.family_birth_identity_enabled&&!x.births)return fail("VoluntaryRelationBirthReadRequired");
    VoluntaryRelationSource out;out.source_identity=c.state().identity;out.kind=kind;out.predecessor_actor_id=predecessor;out.successor_actor_id=successor;out.before_fact_id=before;out.observed_tick=tick;
    for(const auto* actor:{&predecessor,&successor}){auto p=before.empty()?read_actor_presence(c,x.catalog,x.death_origin,*actor):read_actor_presence_before_fact(c,x.catalog,x.death_origin,*actor,tick,before);if(!p.ok)return {false,{},p.error};if(!p.value.alive)return fail("VoluntaryRelationLivingPartiesRequired");if(!before.empty()){if(!p.value.creation_fact_id.empty()){auto r=same_side(c,p.value.creation_fact_id,before);if(!r.ok)return {false,{},r.error};}auto died=x.death_origin(*actor);if(!died.ok)return {false,{},died.error};if(died.value){auto r=same_side(c,died.value->casualty_fact_id,before);if(!r.ok)return {false,{},r.error};}}auto a=x.births?(before.empty()?read_actor_age(c,x.catalog,*x.births,*actor):read_actor_age_before_fact(c,x.catalog,*x.births,*actor,tick,before)):(before.empty()?read_actor_age(c,x.catalog,*actor):read_actor_age_before_fact(c,x.catalog,*actor,tick,before));if(!a.ok)return {false,{},a.error};if(!a.value.adult)return fail("VoluntaryRelationAdultRequired");if(*actor==predecessor)out.predecessor_birth_tick=a.value.birth_tick;else out.successor_birth_tick=a.value.birth_tick;}
    if(kind==VoluntaryRelationKind::biological_child){
        if(!selected.empty()||!x.lineage)return fail("VoluntaryRelationBiologicalSourceRequired");BiologicalLegacyBasisContext biological{c,x.catalog,*x.lineage,x.births,nullptr,x.death_origin};auto origin=before.empty()?read_biological_child_origin(biological,predecessor,successor):read_biological_child_origin_before_fact(biological,predecessor,successor,tick,before);if(!origin.ok)return {false,{},origin.error};if(!origin.value)return fail("VoluntaryRelationBiologicalSourceRequired");out.biological=*origin.value;out.established_tick=origin.value->source_available_tick;if(origin.value->kind==BiologicalChildOriginKind::recorded_birth){auto r=prior(c,origin.value->birth_fact_id,origin.value->creation_fact_id);if(!r.ok)return {false,{},r.error};r=prior(c,origin.value->creation_fact_id,before);if(!r.ok)return {false,{},r.error};}return {true,std::move(out),{}};
    }
    if(selected.empty())return fail("VoluntaryRelationExactSourceRequired");auto order=prior(c,selected,before);if(!order.ok)return {false,{},order.error};out.relation_fact_id=selected;const auto* h=c.state().facts.find(selected);
    if(kind==VoluntaryRelationKind::adoption){
        const auto* fact=x.family.facts.find(selected);bool matches=false;if(fact&&h&&h->id==selected&&h->domain=="family"){
            if(const auto* a=std::get_if<AdoptionFact>(fact)){matches=selected.rfind("action:",0)==0&&h->kind=="family_adoption"&&a->kind==h->kind&&a->success&&a->guardian_actor_id==predecessor&&a->child_actor_id==successor;out.established_tick=a->completed_tick;}
            else if(const auto* a=std::get_if<AdultAdoptionFact>(fact)){matches=selected.rfind("family:",0)==0&&h->kind=="family_adult_adoption"&&a->kind==h->kind&&a->agreement.adopter_actor_id==predecessor&&a->agreement.adoptee_actor_id==successor;out.established_tick=a->agreement.accepted_tick;}
        }if(!matches)return fail("VoluntaryRelationAdoptionSourceRequired");
    }else if(kind==VoluntaryRelationKind::accepted_disciple){
        if(!x.apprenticeships)return fail("VoluntaryRelationApprenticeshipSourceRequired");auto valid=validate_apprenticeship_result_bindings(c,*x.apprenticeships);if(!valid.ok)return {false,{},valid.error};const auto* reply=x.apprenticeships->replies.find(selected);if(!reply||reply->decision!="accepted"||!reply->confirmation||!h||h->id!=selected||h->domain!="family_apprenticeship"||h->kind!="family_apprenticeship_replied"||selected.rfind("apprenticeship:",0)!=0)return fail("VoluntaryRelationApprenticeshipSourceRequired");const auto& source=*reply->confirmation;if(source.teacher_actor_id!=predecessor||source.student_actor_id!=successor)return fail("VoluntaryRelationApprenticeshipPartiesMismatch");
        if(before.empty()){for(const auto& exit:x.apprenticeships->exits.rows())if(exit.second.bond_id==selected)return fail("VoluntaryRelationApprenticeshipEnded");}else{for(const auto& exit:x.apprenticeships->exits.rows())if(exit.second.bond_id==selected){auto side=same_side(c,exit.first,before);if(!side.ok)return {false,{},side.error};}auto bond=read_apprenticeship_bond_before_fact(c,*x.apprenticeships,selected,tick,before);if(!bond.ok)return {false,{},bond.error};if(!bond.value||bond.value->exit_fact_id)return fail("VoluntaryRelationApprenticeshipEnded");}
        const auto* binding=x.apprenticeships->commits.find(selected);if(!binding||serial(c,binding->result_id)<=serial(c,selected)||(!before.empty()&&serial(c,binding->result_id)>=serial(c,before)))return fail("VoluntaryRelationPriorAcceptanceResultRequired");out.established_tick=reply->tick;out.skill_id=source.skill_id;
    }else if(kind==VoluntaryRelationKind::recognized_collateral){
        if(!x.collateral)return fail("VoluntaryRelationRecognitionRequired");auto valid=validate_collateral_recognition_result_bindings(c,*x.collateral);if(!valid.ok)return {false,{},valid.error};auto relation=before.empty()?read_collateral_recognition(c,*x.collateral,selected):read_collateral_recognition_before_fact(c,*x.collateral,selected,tick,before);if(!relation.ok)return {false,{},relation.error};const auto& r=relation.value;if(!((r.first_actor_id==predecessor&&r.second_actor_id==successor)||(r.first_actor_id==successor&&r.second_actor_id==predecessor)))return fail("VoluntaryRelationRecognizedPartiesMismatch");out.established_tick=r.recognized_tick;
    }else return fail("VoluntaryRelationKindRequired");
    if(out.established_tick<0||out.established_tick>tick)return fail("VoluntaryRelationPredatesSource");return {true,std::move(out),{}};
}
}
Outcome<VoluntaryRelationSource> read_current_voluntary_relation(const VoluntaryRelationContext& x,VoluntaryRelationKind kind,const StableId& predecessor,const StableId& successor,const StableId& relation){return read(x,kind,predecessor,successor,relation,x.common.tick(),{});}
Outcome<VoluntaryRelationSource> read_voluntary_relation_before_fact(const VoluntaryRelationContext& x,VoluntaryRelationKind kind,const StableId& predecessor,const StableId& successor,const StableId& relation,Integer tick,const StableId& before){if(before.empty())return {false,{},common_failure("VoluntaryRelationActualBoundaryRequired").error};return read(x,kind,predecessor,successor,relation,tick,before);}
}
